import test from 'node:test';import assert from 'node:assert/strict';import {createHundredHandMileRouteFixture} from '../scripts/check-hundred-hand-mile-player-route.mjs';import {MILE_CONVOY_JOB,MILE_CONVOY_RECORD} from '../src/systems/hundredHandMileTraffic.js';
test('real native convoy crosses finite route through ordinary NPC thrust without pose or outcome writes',async()=>{
 const h=await createHundredHandMileRouteFixture({startOffset:{x:-45,z:-20}});
 try{
  const traffic=h.runtime.getSystem('hundredHandMileTraffic'),world=h.runtime.getSystem('hundredHandMileWorld'),credits=h.s.player.credits;
  console.log('MILE_CONVOY_FIXTURE',JSON.stringify({tick:h.s.tick,mode:h.s.mode,nativeReady:h.runtime.getSystem('physics')._diag?.sg02Ready})); const proof=traffic.proveRoute();assert(proof.ok,proof.reason);assert.equal(traffic.dispatchConvoy(proof).ok,true);
  console.log('MILE_CONVOY_DISPATCH',JSON.stringify({tick:h.s.tick,row:traffic.serialize()})); let crossed=false,origin=false,authorityLost=false;let lastSignature=null;const samples=[]; const observe=()=>{const hull=h.s.entityList.find(e=>e.alive!==false&&e.data?.worldRecordId===MILE_CONVOY_RECORD),entry=h.runtime.getHelpers().npcJobs.get(MILE_CONVOY_JOB),rec=hull&&world.nativeRecord(hull),body=rec?.body,row=traffic.serialize();return {tick:h.s.tick,outcome:row.outcome,origin:row.observedOrigin,crossed:row.observedCrossing,witnessed:row.witnessedByPlayer,hullId:hull?.id,life:hull?.occupantGeneration,alive:hull?.alive,hull:hull?.hull,entitySame:!!hull&&h.s.entities.get(hull.id)===hull,entryEntity:entry?.entityId,entryJob:entry?.job.id,claim:hull?.data?.jobId,nativePresent:!!rec,native: hull&&world.nativePosition(hull),velocity:body?.linvel(),heading:hull?.rot,scalar:hull?.pos,phase:entry?.job.phase,progress:entry?.job.progress,routeIndex:entry?.job.routeIndex,control:entry?.control,berthHold:entry?.berthHold,closeCallUntil:entry?.closeCallUntil,threat:entry?.threatId,intent:hull?.data?.intent,actuator:hull?.data?.propulsionRuntime,playerDistance:hull?Math.hypot(h.player().pos.x-hull.pos.x,h.player().pos.z-hull.pos.z):null};};
  for(let i=0;i<3600&&!traffic.serialize().outcome;i++){
   h.step();const row=traffic.serialize();origin ||= row.observedOrigin;crossed ||= row.observedCrossing;
   const current=observe(),signature=JSON.stringify([current.phase,current.origin,current.crossed,current.outcome,current.hullId,current.life,current.nativePresent,current.control?.holder,current.berthHold,current.threat]); if(i%120===0||signature!==lastSignature){samples.push(current);console.log('MILE_CONVOY_PROGRESS',JSON.stringify(current));lastSignature=signature;} if(!row.outcome&&(!current.entitySame||!current.nativePresent||current.claim!==MILE_CONVOY_JOB||current.entryEntity!==current.hullId)){authorityLost=true;console.log('MILE_CONVOY_AUTHORITY_LOSS',JSON.stringify(current));break;}
  }
  console.log('MILE_NATIVE_CONVOY',JSON.stringify({samples,authorityLost,terminal:traffic.serialize()}));
  assert.equal(traffic.serialize().outcome,'arrived');assert(origin&&crossed);assert.equal(traffic.serialize().witnessedByPlayer,true);
  assert.equal(h.s.player.credits,credits,'focused traffic-owner dispatch does not fabricate earned graph chapters');
  assert.equal(h.system.serialize().finalConvoyJobId,null,'this is physical traffic proof, not earned campaign dispatch');
  h.step(10);assert.equal(h.runtime.getHelpers().npcJobs.get(MILE_CONVOY_JOB),null);assert.equal(traffic.dispatchConvoy(proof).duplicate,true);
 }finally{h.dispose()}
});

